        ready() {
          console.log("[hello] ready:", this.langs.length, "种问候语已就绪");
        },
        proto: {
          /** 根据当前语言与姓名重算问候语 */
          refresh() {
            const lang = this.langs.find((item) => item.id === this.langId) || this.langs[0];
            this.flag = lang.flag;
            this.word = lang.word;
            const who = this.name.trim() === "" ? "World" : this.name.trim();
            this.greeting = lang.word + ", " + who + "!";
          },
          showHint(text) {
            this.hint = text;
            if (hintTimer) clearTimeout(hintTimer);
            hintTimer = setTimeout(() => {
              this.hint = "";
            }, 2400);
          },
          onNameInput(event) {
            this.name = (event && event.target && event.target.value) || "";
            this.refresh();
            console.log("[hello] name ->", this.name);
          },
          pickLang(id) {
            if (id === this.langId) return;
            this.langId = id;
            this.refresh();
            this.showHint("已切换为「" + this.word + "」");
            console.log("[hello] lang ->", id);
          },
          nextLang() {
            const rest = this.langs.filter((item) => item.id !== this.langId);
            const picked = rest[Math.floor(Math.random() * rest.length)] || this.langs[0];
            this.langId = picked.id;
            this.refresh();
            this.showHint("已切换为「" + this.word + "」");
            console.log("[hello] lang ->", picked.id);
          },
          sayHello() {
            this.bumpTimes += 1;
            const rest = EMOJIS.filter((item) => item !== this.emoji);
            this.emoji = rest[Math.floor(Math.random() * rest.length)] || "👋";
            this.showHint(this.greeting + " 很高兴见到你 🎉");
            console.log("[hello] hello x", this.bumpTimes);
          },
        },
      };
    };
  </script>
</template>
